const {
  supabaseAdmin,
  serviceRoleEnvVar,
  serviceRoleKeyRole,
} = require('./supabase');
require('dotenv').config();

const SERVICE_KEY_CANDIDATES = [
  'SUPABASE_SERVICE_ROLE_KEY',
  'SUPABASE_SERVICE_KEY',
  'SUPABASE_SECRET_KEY',
  'SUPABASE_KEY',
];

function assertAdminSeedingConfig() {
  const presentVars = SERVICE_KEY_CANDIDATES.filter(name => Boolean(process.env[name]));

  console.log('🔐 Seed auth diagnostics:');
  console.log(`   - Service key vars present: ${presentVars.length ? presentVars.join(', ') : 'none'}`);
  console.log(`   - Active admin key source: ${serviceRoleEnvVar || 'none'}`);
  console.log(`   - Active admin JWT role: ${serviceRoleKeyRole || 'unknown'}`);

  if (!supabaseAdmin) {
    throw new Error(
      'Missing service-role key for seeding.\n' +
      'Set SUPABASE_SERVICE_ROLE_KEY (preferred), SUPABASE_SERVICE_KEY, or SUPABASE_SECRET_KEY in .env.'
    );
  }

  if (serviceRoleKeyRole !== 'service_role') {
    throw new Error(
      `Invalid admin key in ${serviceRoleEnvVar || 'env'}: JWT role is ${serviceRoleKeyRole || 'unknown'}.\n` +
      'Seeding requires a service-role key (role=service_role), not anon/authenticated keys.'
    );
  }
}

