// ─── Helper: Convert camelCase to snake_case ───
function camelToSnake(str) {
  return str.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
}

// ─── Helper: Convert competition object to database row ───
const DECIMAL_SCORE_FIELDS = new Set(['rarity_score', 'trust_score', 'resume_value']);

function convertToDbRow(comp) {
  const row = {};
  for (const [key, value] of Object.entries(comp)) {
    const snakeKey = camelToSnake(key);

    if (Array.isArray(value)) {
      row[snakeKey] = value; // Keep arrays as-is, Postgres will handle
      continue;
    }

    if (DECIMAL_SCORE_FIELDS.has(snakeKey) && value !== null && value !== undefined) {
      const normalized = Number(value);
      row[snakeKey] = Number.isFinite(normalized) ? normalized : null;
      continue;
    }

    row[snakeKey] = value;
  }
  return row;
}

// ─── Main Seed Function ───
async function seedCompetitions() {
  console.log('\n🌱 Starting competition seeding...');
  assertAdminSeedingConfig();
  console.log(`📊 Total competitions to seed: ${ALL_COMPETITIONS.length}\n`);

  let successCount = 0;
  const errors = [];

  for (let i = 0; i < ALL_COMPETITIONS.length; i++) {
    const comp = ALL_COMPETITIONS[i];
    const dbRow = convertToDbRow(comp);

    try {
      // Use UPSERT to handle duplicates gracefully
      const { data, error } = await supabaseAdmin
        .from('competitions')
        .upsert([dbRow], { onConflict: 'id' });

      if (error) {
        throw error;
      }

      successCount++;
      console.log(`✅ Seeding [${i + 1}/95]: ${comp.title}`);
    } catch (err) {
      console.error(`❌ Error seeding [${i + 1}/95]: ${comp.title}`);
      console.error(`   Error: ${err.message}`);
      errors.push({ id: comp.id, title: comp.title, error: err.message });
    }
  }

  // Final Report
  console.log('\n' + '='.repeat(60));
  console.log(`✅ SEEDING COMPLETE`);
  console.log('='.repeat(60));
  console.log(`📈 Successfully seeded: ${successCount}/${ALL_COMPETITIONS.length}`);

  if (errors.length > 0) {
    console.log(`\n⚠️  Errors encountered: ${errors.length}`);
    errors.forEach(e => {
      console.log(`   - ${e.id}: ${e.title} — ${e.error}`);
    });
    process.exit(1);
  } else {
    console.log('\n🎉 All competitions seeded successfully!');
    process.exit(0);
  }
}

// Run seed
seedCompetitions().catch(err => {
  console.error('🔥 Fatal error during seeding:');
  console.error(err);
  process.exit(1);
});
